<template>
  <section class="policy-page" v-loading="loading">
    <header class="page-header">
      <div><h1>物资归属配置</h1><p>维护 Item 的库存管理、领用责任与默认经济归属；采购单据自动带出，历史业务不被覆盖。</p></div>
      <div class="header-actions"><el-button @click="$router.push('/master/items')">返回物料列表</el-button><el-button :loading="saving" @click="saveDraft">保存草稿</el-button><el-button type="success" :loading="saving" @click="activate">保存并启用</el-button></div>
    </header>
    <el-alert class="policy-alert" title="库存管理与经济归属独立配置；采购员只使用处理策略，不维护会计科目。" type="info" :closable="false" show-icon />

    <main class="policy-grid">
      <section class="card item-readonly"><h2>物料只读信息</h2><dl><dt>Item编码</dt><dd>{{ item.item_code || '-' }}</dd><dt>物料名称</dt><dd>{{ item.item_name || '-' }}</dd><dt>物料类型</dt><dd>{{ itemTypeText(item.item_type) }}</dd><dt>Item类目</dt><dd>{{ item.category && item.category.category_name || '-' }}</dd><dt>基本单位</dt><dd>{{ item.unit && (item.unit.symbol || item.unit.unit_name) || '-' }}</dd><dt>当前状态</dt><dd><el-tag size="mini" type="success">{{ item.status === 'enabled' ? '启用' : '停用' }}</el-tag></dd></dl><el-button type="text" icon="el-icon-arrow-right" @click="$router.push(`/inventory/balances?item_id=${item.id}`)">查看库存余额</el-button><el-button v-if="form.is_stock_managed" type="text" icon="el-icon-bell" @click="$router.push(`/inventory/alerts/config?item_id=${item.id}`)">配置库存预警</el-button></section>

      <section class="card policy-form"><h2>默认管理属性</h2>
        <div class="attribute-grid">
          <label><span>是否库存管理</span><el-switch v-model="form.is_stock_managed" active-text="是" inactive-text="否" active-color="#07883f" @change="normalizeStock" /></label>
          <label><span>物资管理属性</span><el-select v-model="form.template_code" @change="applyTemplate"><el-option v-for="row in templates" :key="row.value" :label="row.label" :value="row.value" /></el-select></label>
          <label><span>是否需要责任人</span><el-switch v-model="form.requires_custodian" active-text="是" inactive-text="否" active-color="#07883f" /></label>
          <label><span>是否可归还</span><el-switch v-model="form.is_returnable" :disabled="!form.requires_custodian" active-text="是" inactive-text="否" active-color="#07883f" /></label>
          <label><span>是否需要资产化</span><el-switch v-model="form.requires_capitalization" active-text="是" inactive-text="否" active-color="#07883f" /></label>
          <label><span>序列号策略</span><el-select v-model="form.serial_tracking_mode"><el-option label="无需逐件编号" value="none" /><el-option label="按需逐件编号" value="optional" /><el-option label="必须逐件编号" value="required" /></el-select></label>
        </div>
        <div class="divider" /><h3>默认经济归属</h3>
        <div class="route-grid"><button v-for="route in routes" :key="route.value" type="button" :class="['route',{selected:form.future_route===route.value}]" @click="applyRoute(route.value)"><i :class="route.icon" /><b>{{ route.label }}</b><small>{{ route.help }}</small><em v-if="form.future_route===route.value" class="el-icon-check" /></button></div>
        <div class="detail-grid">
          <label><span>领用后归属</span><el-select v-model="form.future_bearer_type"><el-option label="公司公共" value="company" /><el-option label="部门办公费用" value="department" /><el-option label="员工责任" value="employee" /><el-option label="工单承担（预留）" value="work_order" /><el-option label="销售订单承担（预留）" value="sales_order" /></el-select></label>
          <label><span>默认承担部门</span><el-input disabled placeholder="后续按部门权限选择（可选）"><i slot="suffix" class="el-icon-search" /></el-input></label>
          <label><span>采购后处理策略</span><el-select v-model="form.post_purchase_action"><el-option v-for="option in actions" :key="option.value" :label="option.label" :value="option.value" /></el-select></label>
          <label><span>消耗/确认方式</span><el-select v-model="form.consumption_confirmation_mode"><el-option label="无需确认" value="none" /><el-option label="领用确认" value="issue" /><el-option label="资产验收" value="asset_acceptance" /><el-option label="服务验收" value="service_acceptance" /></el-select></label>
          <label><span>变更原因 <b>*</b></span><el-input v-model.trim="form.change_reason" maxlength="200" placeholder="首次配置可留空；新版本必填" /></label>
          <label class="remark"><span>备注</span><el-input v-model="form.remark" maxlength="200" show-word-limit placeholder="请输入备注，最多 200 字" /></label>
        </div>
        <p class="immutable"><i class="el-icon-warning-outline" />保存后只影响未来采购与领用；已确认采购、库存、财务事实保持不变。</p>
      </section>

      <section class="card validation"><h2>保存前校验</h2><ul><li :class="item.unit_id?'pass':'fail'"><i class="el-icon-circle-check" />基本单位已设置</li><li :class="form.template_code?'pass':'fail'"><i class="el-icon-circle-check" />物资管理属性完整</li><li :class="stockRouteValid?'pass':'fail'"><i class="el-icon-circle-check" />库存管理与归属策略一致</li><li :class="returnableValid?'pass':'fail'"><i class="el-icon-circle-check" />责任人规则有效</li><li class="pass"><i class="el-icon-circle-check" />序列号规则有效</li></ul><div class="flow"><h3>策略说明</h3><div><i class="el-icon-shopping-cart-2" /><em>→</em><i class="el-icon-box" /><em>→</em><i class="el-icon-user" /><em>→</em><i class="el-icon-coin" /></div><p>采购到货　{{ form.is_stock_managed ? '库存处理' : '后续处理' }}　{{ bearerText }}</p></div><div class="preview"><h3>结果预览</h3><p>库存台账 <b>{{ form.is_stock_managed ? '是' : '否' }}</b></p><p>领用单类型 <b>{{ actionText }}</b></p><p>成本去向 <b>{{ routeText }}</b></p></div></section>
    </main>
    <section class="card purchase-preview"><h2>未来采购带出预览</h2><el-table :data="[previewRow]" border size="small"><el-table-column prop="purpose" label="采购用途" /><el-table-column prop="stock" label="库存管理"><template slot-scope="{row}"><b :class="row.stock==='是'?'green':'red'">{{ row.stock }}</b></template></el-table-column><el-table-column prop="route" label="经济归属" /><el-table-column prop="custodian" label="是否责任人"><template slot-scope="{row}"><b :class="row.custodian==='是'?'green':'red'">{{ row.custodian }}</b></template></el-table-column><el-table-column prop="capitalization" label="资产化"><template slot-scope="{row}"><b :class="row.capitalization==='是'?'green':'red'">{{ row.capitalization }}</b></template></el-table-column><el-table-column prop="next" label="后续业务" /></el-table></section>
  </section>
</template>

<script>
import { getEntity, getItemMaterialPolicy, saveItemMaterialPolicyDraft, activateItemMaterialPolicy } from '../../../api/erp/master'
const blank = () => ({ template_code: 'inventory_material', is_stock_managed: true, inventory_management_mode: 'standard', requires_custodian: false, is_returnable: false, requires_capitalization: false, serial_tracking_mode: 'none', post_purchase_action: 'inventory_receipt', consumption_confirmation_mode: 'none', future_route: 'inventory', future_bearer_type: 'company', change_reason: '', remark: '' })
export default { name: 'ItemMaterialPolicy', data () { return { loading: false, saving: false, item: {}, form: blank(), templates: [{ value: 'inventory_material', label: '库存材料/商品' }, { value: 'office_consumable', label: '库存后领用消耗' }, { value: 'low_value_custody', label: '低值责任物资' }, { value: 'fixed_asset_pending', label: '固定资产待处理' }, { value: 'direct_non_stock', label: '直接非库存处理' }, { value: 'work_order_cost', label: '工单成本意图' }, { value: 'sales_order_direct_cost', label: '订单直接费用意图' }], actions: [{ value: 'inventory_receipt', label: '到货入库' }, { value: 'issue_confirmation', label: '到货入库后领用确认' }, { value: 'asset_acceptance', label: '资产验收（预留）' }, { value: 'expense_confirmation', label: '费用确认（预留）' }, { value: 'work_order_cost', label: '工单直接成本（预留）' }, { value: 'sales_order_direct_cost', label: '订单直接费用（预留）' }], routes: [{ value: 'inventory', label: '库存材料/商品', help: '用于生产或销售的库存材料或商品。', icon: 'el-icon-box' }, { value: 'expense', label: '库存后领用消耗', help: '办公耗材先入库存，领用后确认费用。', icon: 'el-icon-notebook-2' }, { value: 'asset', label: '固定资产待验收', help: '未来资产验收；本阶段只保存意图。', icon: 'el-icon-office-building' }, { value: 'work_order_cost', label: '生产外协/工单直接成本', help: '未来计入工单实际成本。', icon: 'el-icon-setting' }, { value: 'sales_order_direct_cost', label: '订单直接费用', help: '未来关联订单直接费用。', icon: 'el-icon-document' }, { value: 'direct_expense', label: '直接费用', help: '非库存费用；本阶段只保存路由意图。', icon: 'el-icon-wallet' }] } }, computed: { stockRouteValid () { return this.form.is_stock_managed ? ['inventory', 'expense'].includes(this.form.future_route) : this.form.future_route !== 'inventory' }, returnableValid () { return !this.form.is_returnable || this.form.requires_custodian }, routeText () { return ({ inventory: '库存成本', expense: '部门期间费用', asset: '资产处理意图', work_order_cost: '工单成本意图', sales_order_direct_cost: '订单直接费用意图' })[this.form.future_route] || '直接费用意图' }, actionText () { return (this.actions.find(row => row.value === this.form.post_purchase_action) || {}).label || '-' }, bearerText () { return ({ company: '公司公共', department: '部门承担', employee: '员工责任', work_order: '工单承担', sales_order: '订单承担' })[this.form.future_bearer_type] || '-' }, previewRow () { return { purpose: this.actionText, stock: this.form.is_stock_managed ? '是' : '否', route: this.routeText, custodian: this.form.requires_custodian ? '是' : '否', capitalization: this.form.requires_capitalization ? '是' : '否', next: this.actionText } } }, created () { this.load() }, methods: { async load () { this.loading = true; try { const [item, policy] = await Promise.all([getEntity('items', this.$route.params.id), getItemMaterialPolicy(this.$route.params.id)]); this.item = item.data; const current = policy.data.draft || policy.data.active; if (current) this.form = { ...blank(), ...current } } catch (e) { this.$message.error(e.userMessage || '物资归属策略加载失败') } finally { this.loading = false } }, normalizeStock () { if (this.form.is_stock_managed) { this.form.inventory_management_mode = 'standard'; if (!['inventory', 'expense'].includes(this.form.future_route)) this.applyRoute('inventory') } else { this.form.inventory_management_mode = 'none'; if (this.form.future_route === 'inventory') this.applyRoute('direct_expense') } }, applyTemplate (value) { const map = { inventory_material: 'inventory', office_consumable: 'expense', low_value_custody: 'expense', fixed_asset_pending: 'asset', direct_non_stock: 'direct_expense', work_order_cost: 'work_order_cost', sales_order_direct_cost: 'sales_order_direct_cost' }; this.applyRoute(map[value] || 'inventory'); if (value === 'low_value_custody') Object.assign(this.form, { requires_custodian: true, is_returnable: true }) }, applyRoute (value) { const route = value === 'direct_expense' ? 'expense' : value; const defaults = { inventory: { is_stock_managed: true, post_purchase_action: 'inventory_receipt', consumption_confirmation_mode: 'none', requires_capitalization: false }, expense: { is_stock_managed: true, post_purchase_action: 'issue_confirmation', consumption_confirmation_mode: 'issue', requires_capitalization: false }, asset: { is_stock_managed: false, post_purchase_action: 'asset_acceptance', consumption_confirmation_mode: 'asset_acceptance', requires_capitalization: true }, work_order_cost: { is_stock_managed: false, post_purchase_action: 'work_order_cost', consumption_confirmation_mode: 'service_acceptance', requires_capitalization: false }, sales_order_direct_cost: { is_stock_managed: false, post_purchase_action: 'sales_order_direct_cost', consumption_confirmation_mode: 'service_acceptance', requires_capitalization: false } }; this.form.future_route = route; Object.assign(this.form, defaults[route] || defaults.expense); this.normalizeStock() }, validate () { if (!this.stockRouteValid) return '库存管理与经济归属不一致'; if (!this.returnableValid) return '可归还物资必须启用责任人管理'; return '' }, async saveDraft () { const error = this.validate(); if (error) return this.$message.error(error); this.saving = true; try { await saveItemMaterialPolicyDraft(this.item.id, this.form); this.$message.success('策略草稿已保存'); await this.load() } catch (e) { this.$message.error(e.userMessage || '策略草稿保存失败') } finally { this.saving = false } }, async activate () { const error = this.validate(); if (error) return this.$message.error(error); this.saving = true; try { await activateItemMaterialPolicy(this.item.id, this.form); this.$message.success('物资归属策略已启用'); await this.load() } catch (e) { this.$message.error(e.userMessage || '策略启用失败') } finally { this.saving = false } }, itemTypeText (v) { return ({ finished_product: '成品', semi_finished: '半成品', raw_material: '原材料', packaging: '包装物', service: '服务' })[v] || v || '-' } } }
</script>

<style scoped>
