ize:13px}.route small{margin-top:5px;color:#6d7887;font-size:11px;line-height:1.4}.route em{position:absolute;top:8px;right:8px;width:18px;height:18px;border-radius:50%;background:#07883f;color:#fff;text-align:center;line-height:18px;font-style:normal}.detail-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-top:16px}.detail-grid b{color:#df3030}.detail-grid .remark{grid-column:span 3}.immutable{margin:16px 0 0;padding:11px 12px;border:1px solid #ffd59a;border-radius:5px;background:#fff8ec;color:#bf6911;font-size:12px}.immutable i{margin-right:6px;font-size:16px}.validation ul{margin:0;padding:0;list-style:none}.validation li{display:flex;align-items:center;gap:9px;padding:10px 0;border-bottom:1px solid #e8edf2;font-size:13px}.validation li i{font-size:18px}.pass{color:#07883f}.fail{color:#df3030}.flow{padding:16px 0;border-bottom:1px solid #e8edf2}.flow h3,.preview h3{margin:0 0 12px;font-size:15px}.flow div{display:flex;align-items:center;justify-content:space-between;color:#07883f}.flow i{width:33px;height:33px;border-radius:50%;background:#e7f7ee;text-align:center;line-height:33px;font-size:17px}.flow em{color:#788596;font-style:normal}.flow p{margin:11px 0 0;font-size:11px;color:#586675}.preview{margin-top:16px;border:1px solid #e0e6ed;border-radius:5px;padding:12px}.preview p{display:flex;justify-content:space-between;margin:9px 0;font-size:13px}.preview b{color:#07883f}.purchase-preview{margin-top:14px;padding:16px}.purchase-preview h2{margin-bottom:14px}.green{color:#07883f}.red{color:#df3030}@media(max-width:1360px){.policy-grid{grid-template-columns:210px minmax(560px,1fr) 250px}.attribute-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.route-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:1080px){.policy-grid{grid-template-columns:1fr}.item-readonly,.validation{display:grid;grid-template-columns:1fr 1fr;gap:16px}.item-readonly h2,.validation h2{grid-column:1/-1;margin-bottom:0}.route-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:720px){.policy-page{padding:16px 12px}.page-header{display:block}.header-actions{margin-top:14px;flex-wrap:wrap}.attribute-grid,.detail-grid,.route-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.detail-grid .remark{grid-column:span 1}.item-readonly,.validation{display:block}.item-readonly h2,.validation h2{margin-bottom:16px}.purchase-preview{overflow-x:auto}.purchase-preview .el-table{min-width:720px}}
